\.
COPY public.ai_chat_messages (id, conversation_id, role, content, intent, confidence, action_taken, created_at) FROM stdin;
\.
COPY public.ai_job_estimations (id, garage_id, job_card_id, vehicle_id, service_type, estimated_hours, estimated_cost, confidence, reasoning, actual_hours, actual_cost, created_at) FROM stdin;
\.
