\.
COPY public.ai_parts_recommendations (id, garage_id, job_card_id, vehicle_id, recommended_parts, reasoning, total_estimated_cost, confidence, status, applied_to_job_card, created_at) FROM stdin;
\.
COPY public.ai_schedule_optimizations (id, garage_id, optimization_type, suggestions, reasoning, potential_time_saved, status, applied_at, created_at) FROM stdin;
\.
COPY public.ai_scheduling_rules (id, garage_id, name, priority, consider_technician_skills, consider_technician_workload, consider_part_availability, consider_customer_preference, buffer_time_between_jobs, max_jobs_per_technician, is_active, created_at, updated_at) FROM stdin;
\.
COPY public.ai_service_suggestions (id, vehicle_id, suggestion_type, service_description, estimated_cost, priority, reasoning, confidence, related_job_card_id, status, presented_at, decided_at, created_at) FROM stdin;
\.
COPY public.ai_video_analysis (id, customer_id, vehicle_id, video_url, video_size, video_duration, uploaded_at, analysis_status, ai_model, detected_issues, confidence, suggested_services, estimated_cost, priority_level, triage_category, appointment_scheduled, appointment_id, analysis_notes, processed_at, created_at) FROM stdin;
